	const host = options._createHostRecord(owner._parentDom);
	const canWalk =
		owner._renderCallbacks != null &&
		hooks._list != null &&
		hooks._pendingEffects != null;

	let node = owner._vnode;
	let lineage = options._createLineage(node);
